using System.IO; using System.Net; using System.Text; using System.Text.Json; namespace CloudServer;
public static class Api {
 static readonly JsonSerializerOptions json=new(JsonSerializerDefaults.Web);
 public static async Task Run(StateStore store){var l=new HttpListener();l.Prefixes.Add("http://localhost:5050/");l.Start();while(true){var c=await l.GetContextAsync();_=Task.Run(()=>Handle(c,store));}}
 static async Task Handle(HttpListenerContext c,StateStore store){try{var p=c.Request.Url?.AbsolutePath??"/";if(p=="/api/health"){await Reply(c,200,new{status="ok",product="i-NET-PROMO Cloudservice"});return;}if(p=="/api/login"&&c.Request.HttpMethod=="POST"){var q=await JsonSerializer.DeserializeAsync<Login>(c.Request.InputStream,json);var u=store.State.Users.FirstOrDefault(x=>x.UserName.Equals(q?.UserName,StringComparison.OrdinalIgnoreCase));if(u==null||!StateStore.Verify(q?.Password??"",u.PasswordHash)){await Reply(c,401,new{error="Anmeldung fehlgeschlagen"});return;}await Reply(c,200,new{u.Id,u.UserName,u.DisplayName,u.IsAdmin,u.QuotaBytes});return;}if(p=="/api/users"){await Reply(c,200,store.State.Users.Select(u=>new{u.Id,u.UserName,u.DisplayName,u.IsAdmin,u.QuotaBytes}));return;}if(p=="/api/storage"){await Reply(c,200,store.State.Storage);return;}if(p=="/api/files"&&c.Request.HttpMethod=="GET"){var sid=c.Request.QueryString["storageId"]??"";var rel=c.Request.QueryString["path"]??"";var s=store.State.Storage.FirstOrDefault(x=>x.Id==sid);if(s==null){await Reply(c,404,new{error="Speicher nicht gefunden"});return;}var dir=SafePath(s.Path,rel);if(dir==null||!Directory.Exists(dir)){await Reply(c,404,new{error="Ordner nicht gefunden"});return;}var items=Directory.EnumerateFileSystemEntries(dir).Select(x=>{var isDir=Directory.Exists(x);var fi=isDir?null:new FileInfo(x);return new{Name=Path.GetFileName(x),IsDirectory=isDir,Size=fi?.Length??0,ModifiedUtc=isDir?Directory.GetLastWriteTimeUtc(x):fi!.LastWriteTimeUtc};});await Reply(c,200,items);return;}if(p=="/api/folders"&&c.Request.HttpMethod=="POST"){var q=await JsonSerializer.DeserializeAsync<FolderRequest>(c.Request.InputStream,json);var s=store.State.Storage.FirstOrDefault(x=>x.Id==q?.StorageId);var dir=s==null?null:SafePath(s.Path,Path.Combine(q?.Path??"",q?.Name??""));if(dir==null){await Reply(c,400,new{error="Ungültiger Pfad"});return;}Directory.CreateDirectory(dir);await Reply(c,201,new{ok=true});return;}if(p=="/api/upload"&&c.Request.HttpMethod=="POST"){var sid=c.Request.QueryString["storageId"]??"";var rel=c.Request.QueryString["path"]??"";var name=Path.GetFileName(c.Request.QueryString["name"]??"");var s=store.State.Storage.FirstOrDefault(x=>x.Id==sid);var file=s==null?null:SafePath(s.Path,Path.Combine(rel,name));if(file==null||string.IsNullOrWhiteSpace(name)){await Reply(c,400,new{error="Ungültiger Upload"});return;}Directory.CreateDirectory(Path.GetDirectoryName(file)!);await using(var fs=File.Create(file))await c.Request.InputStream.CopyToAsync(fs);await Reply(c,201,new{ok=true});return;}if(p=="/api/download"&&c.Request.HttpMethod=="GET"){var sid=c.Request.QueryString["storageId"]??"";var rel=c.Request.QueryString["path"]??"";var s=store.State.Storage.FirstOrDefault(x=>x.Id==sid);var file=s==null?null:SafePath(s.Path,rel);if(file==null||!File.Exists(file)){await Reply(c,404,new{error="Datei nicht gefunden"});return;}c.Response.StatusCode=200;c.Response.ContentType="application/octet-stream";c.Response.ContentLength64=new FileInfo(file).Length;await using(var fs=File.OpenRead(file))await fs.CopyToAsync(c.Response.OutputStream);c.Response.Close();return;}
if(p=="/api/delete"&&c.Request.HttpMethod=="POST"){var q=await JsonSerializer.DeserializeAsync<PathRequest>(c.Request.InputStream,json);var s=store.State.Storage.FirstOrDefault(x=>x.Id==q?.StorageId);var target=s==null?null:SafePath(s.Path,q?.Path??"");if(target==null){await Reply(c,400,new{error="Ungültiger Pfad"});return;}if(File.Exists(target))File.Delete(target);else if(Directory.Exists(target))Directory.Delete(target,true);else{await Reply(c,404,new{error="Nicht gefunden"});return;}await Reply(c,200,new{ok=true});return;}if(p=="/api/rename"&&c.Request.HttpMethod=="POST"){var q=await JsonSerializer.DeserializeAsync<RenameRequest>(c.Request.InputStream,json);var s=store.State.Storage.FirstOrDefault(x=>x.Id==q?.StorageId);var src=s==null?null:SafePath(s.Path,q?.Path??"");var parent=src==null?null:Path.GetDirectoryName(src);var dst=s==null||parent==null?null:SafePath(s.Path,Path.GetRelativePath(s.Path,Path.Combine(parent,Path.GetFileName(q?.NewName??""))));if(src==null||dst==null||string.IsNullOrWhiteSpace(q?.NewName)){await Reply(c,400,new{error="Ungültiger Pfad"});return;}if(File.Exists(src))File.Move(src,dst);else if(Directory.Exists(src))Directory.Move(src,dst);else{await Reply(c,404,new{error="Nicht gefunden"});return;}await Reply(c,200,new{ok=true});return;}if(p=="/api/shares"&&c.Request.HttpMethod=="GET"){await Reply(c,200,store.State.Shares.Select(s=>new{s.Id,s.OwnerUserId,s.TargetUserId,s.StorageId,s.RelativePath,s.CanWrite,s.CreatedUtc}));return;}
if(p=="/api/shares"&&c.Request.HttpMethod=="POST"){var q=await JsonSerializer.DeserializeAsync<ShareRequest>(c.Request.InputStream,json);if(q==null||!store.State.Users.Any(u=>u.Id==q.TargetUserId)||!store.State.Storage.Any(s=>s.Id==q.StorageId)){await Reply(c,400,new{error="Ungültige Freigabe"});return;}var grant=new ShareGrant{OwnerUserId=q.OwnerUserId,TargetUserId=q.TargetUserId,StorageId=q.StorageId,RelativePath=q.RelativePath??"",CanWrite=q.CanWrite};store.State.Shares.Add(grant);store.Save();await Reply(c,201,grant);return;}await Reply(c,404,new{error="Not found"});}catch(Exception e){await Reply(c,500,new{error=e.Message});}}
 static string? SafePath(string root,string relative){var fullRoot=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;var full=Path.GetFullPath(Path.Combine(root,relative??""));return (full+Path.DirectorySeparatorChar).StartsWith(fullRoot,StringComparison.OrdinalIgnoreCase)?full:null;} sealed record FolderRequest(string StorageId,string? Path,string Name); sealed record PathRequest(string StorageId,string Path); sealed record RenameRequest(string StorageId,string Path,string NewName); static async Task Reply(HttpListenerContext c,int status,object o){var b=Encoding.UTF8.GetBytes(JsonSerializer.Serialize(o,json));c.Response.StatusCode=status;c.Response.ContentType="application/json; charset=utf-8";c.Response.ContentLength64=b.Length;await c.Response.OutputStream.WriteAsync(b);c.Response.Close();}
 sealed record Login(string UserName,string Password); sealed record ShareRequest(string OwnerUserId,string TargetUserId,string StorageId,string? RelativePath,bool CanWrite);
}
